#!/bin/bash
# build-android.sh [errors] [files]: build the Android engine library from /bo1/p32tree (generated by build-p32.sh),
# inside the bo1-x64 container. ABI=arm64-v8a (default) or ABI=x86_64 (for the emulator, android-emulator-setup.sh).
#   - SDL2 for Android, with the NDK's own clang (once): /bo1/android/sdl/{include/SDL2,lib/libSDL2.so}
#   - libbo1.so, libmain.so (the loader stub) and bo1_boot_test with the patched clang (/bo1/llvm/build, see
#     tools/p32/*.patch: the NDK's clang 21 has the same __ptr32 store bug) against the NDK's sysroot and runtime
#     libraries.
# API 26: below 29 thread-locals are emulated (allocated with malloc, which inside libbo1.so is the low heap).
NDK=/bo1/ndk/ndk-r30/android-ndk-r30
TC=$NDK/toolchains/llvm/prebuilt/linux-x86_64
API=26
A=/bo1/android
ABI=${ABI:-arm64-v8a}
# the Vulkan renderer's bridge needs DXVK's headers (build-dxvk.sh builds the library the APK carries)
DXVK=${DXVK-$([ -d /bo1/dxvk/src/include/native ] && echo /bo1/dxvk/src)}
if [ "$ABI" = x86_64 ]; then
  FFMPEG=${FFMPEG-$([ -f /bo1/ffmpeg/android-x86_64/lib/libavcodec.a ] && echo /bo1/ffmpeg/android-x86_64)}
  TRIPLE=x86_64-linux-android$API; ARCH=x64; PROCESSOR=x86_64; SDLDIR=$A/sdl-x86_64; SDLBUILD=$A/sdl-build-x86_64; B=build/android-x86_64
else
  FFMPEG=${FFMPEG-$([ -f /bo1/ffmpeg/android-arm64-v8a/lib/libavcodec.a ] && echo /bo1/ffmpeg/android-arm64-v8a)}
  TRIPLE=aarch64-linux-android$API; ARCH=arm64; PROCESSOR=aarch64; SDLDIR=$A/sdl; SDLBUILD=$A/sdl-build; B=build/android
fi

if [ ! -f $SDLDIR/lib/libSDL2.so ]; then
  cmake -S $A/SDL2 -B $SDLBUILD -G Ninja -DCMAKE_TOOLCHAIN_FILE=$NDK/build/cmake/android.toolchain.cmake \
    -DANDROID_ABI=$ABI -DANDROID_PLATFORM=android-$API -DCMAKE_BUILD_TYPE=Release -DSDL_STATIC=OFF -DSDL_TEST=OFF \
    > $SDLBUILD.configure.log 2>&1 || { tail -20 $SDLBUILD.configure.log; exit 1; }
  nice -n 19 ionice -c3 ninja -C $SDLBUILD -j ${JOBS:-6} > $SDLBUILD.build.log 2>&1 || { grep -m5 -A8 "error:" $SDLBUILD.build.log; exit 1; }
  mkdir -p $SDLDIR/include/SDL2 $SDLDIR/lib
  cp $A/SDL2/include/*.h $SDLDIR/include/SDL2/
  cp $SDLBUILD/include-config-release/SDL2/SDL_config.h $SDLDIR/include/SDL2/ 2>/dev/null \
    || cp $SDLBUILD/include/SDL2/SDL_config.h $SDLDIR/include/SDL2/ 2>/dev/null \
    || cp $A/SDL2/include/SDL_config_android.h $SDLDIR/include/SDL2/SDL_config.h
  cp $SDLBUILD/libSDL2.so $SDLDIR/lib/
  echo "SDL2 ($ABI): $(ls -la $SDLDIR/lib/libSDL2.so | awk '{print $5}') bytes"
fi

# the patched clang has no runtime libraries of its own: the NDK's (builtins, libunwind) are the same version
[ -e /bo1/llvm/build/lib/clang/21/lib ] || ln -s $TC/lib/clang/21/lib /bo1/llvm/build/lib/clang/21/lib

cd /bo1/p32tree || exit 1
mkdir -p build
[ -f $B/build.ninja ] || cmake -S . -B $B -G Ninja -DBO1_NATIVE=ON -DBO1_NATIVE_ARCH=$ARCH -DBO1_NATIVE_ANDROID=ON -DBO1_ANDROID_SDL2=$SDLDIR -DBO1_NATIVE_DXVK=$DXVK -DBO1_NATIVE_FFMPEG=$FFMPEG \
  -DCMAKE_SYSTEM_NAME=Linux -DCMAKE_SYSTEM_PROCESSOR=$PROCESSOR -DCMAKE_SYSROOT=$TC/sysroot \
  -DCMAKE_C_COMPILER=/bo1/llvm/build/bin/clang -DCMAKE_CXX_COMPILER=/bo1/llvm/build/bin/clang++ \
  -DCMAKE_C_COMPILER_TARGET=$TRIPLE -DCMAKE_CXX_COMPILER_TARGET=$TRIPLE \
  -DCMAKE_FIND_ROOT_PATH=$TC/sysroot -DCMAKE_FIND_ROOT_PATH_MODE_LIBRARY=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_INCLUDE=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_PACKAGE=ONLY -DCMAKE_FIND_ROOT_PATH_MODE_PROGRAM=NEVER \
  "-DCMAKE_EXE_LINKER_FLAGS=-fuse-ld=lld" "-DCMAKE_SHARED_LINKER_FLAGS=-fuse-ld=lld" \
  -DCMAKE_BUILD_TYPE=${BUILD_TYPE:-Release} > $B.configure.log 2>&1 || { tail -30 $B.configure.log; exit 1; }
nice -n 19 ionice -c3 ninja -C $B -j ${JOBS:-6} -k 0 > $B/build.log 2>&1
echo "ninja exit=$?  failed TUs: $(grep -c "^FAILED" $B/build.log)  errors: $(grep -c "error:" $B/build.log)"
grep -E "error:" $B/build.log | sed -E "s/^[^ ]+: //" | sed -E "s/'[^']*'/'X'/g" | sort | uniq -c | sort -rn | head -${1:-40}
echo "--- by file"
grep -E "error:" $B/build.log | cut -d: -f1 | sed "s#/bo1/p32tree/##" | sort | uniq -c | sort -rn | head -${2:-25}
ls -la $B/bin 2>/dev/null
